SELECT b.*,c.name categoryName, u.username sellerName FROM second_book b LEFT JOIN category c ON b.category_id = c.id LEFT JOIN user u ON b.seller_id = u.id WHERE b.status = 1
AND b.category_id = #{categoryId}
ORDER BY b.id DESC LIMIT #{offset}, #{size}

mapper.update:
UPDATE second_book
SET name = #{name}, author = #{author}, price = #{price}, level = #{level},
    book_desc = #{bookDesc}, image = #{image}, seller_id = #{sellerId},
    category_id = #{categoryId}

        , status = #{status}

WHERE id = #{id}
